Ui.Script:
-- ── Strings (GlobalStrings.lua, verbatim) ─────────────────────────────────────────────── local DUEL_REQUESTED = "%s has challenged you to a duel." -- l.957 local DUEL_OUTOFBOUNDS_TIMER = "Exiting duel area, you will forfeit in %d %s." -- l.956 local ACCEPT = "Accept" local DECLINE = "Decline"
-- ── The challenge dialog — StaticPopup.lua l.1103-1116, verbatim ──────────────────────── -- No accept-guard flag (unlike PARTY_INVITE): the ref's entry declines only on an explicit -- OnCancel, so a timeout or an override hides it WITHOUT sending anything. That is not an -- oversight to "fix" — the server's own 60 s is not a thing either; an unanswered challenge -- simply sits until one side acts. ESC does decline (hideOnEscape routes through OnCancel). StaticPopupDialogs["DUEL_REQUESTED"] = { text = DUEL_REQUESTED, button1 = ACCEPT, button2 = DECLINE, sound = "igPlayerInvite", OnAccept = function() AcceptDuel() end, OnCancel = function() CancelDuel() end, timeout = 60, hideOnEscape = 1, }
-- ── The out-of-bounds warning — StaticPopup.lua l.1117-1120, verbatim ─────────────────── -- Two fields and nothing else: the engine's countdown branch owns the text. StaticPopupDialogs["DUEL_OUTOFBOUNDS"] = { text = DUEL_OUTOFBOUNDS_TIMER, timeout = 10, }
-- ── The UIParent event arms (UIParent.lua l.378-393, verbatim) ────────────────────────── function BenillaDuelDriver_OnEvent() if event == "DUEL_REQUESTED" then StaticPopup_Show("DUEL_REQUESTED", arg1) elseif event == "DUEL_OUTOFBOUNDS" then StaticPopup_Show("DUEL_OUTOFBOUNDS") elseif event == "DUEL_INBOUNDS" then StaticPopup_Hide("DUEL_OUTOFBOUNDS") elseif event == "DUEL_FINISHED" then -- Both, unconditionally: a duel that ends while the challenge popup is still up -- (the other side cancelled first) must not leave it there. StaticPopup_Hide("DUEL_REQUESTED") StaticPopup_Hide("DUEL_OUTOFBOUNDS") end end
